final startIndex = int.tryParse(params['startIndex'] ?? '0') ?? 0;

final extractor = createMetadataExtractor();
final rawPaths = pathsCsv.split(',').map((path) => path.trim());
final tracks = <AudioTrack>[];
for (final rawPath in rawPaths) {
  if (rawPath.isEmpty) continue;
  try {
    tracks.add(await extractor.extractMetadata(rawPath));
  } catch (_) {
    // Fall back to filename-only when extraction fails.
    final base = rawPath.split('/').last;
    tracks.add(AudioTrack(path: rawPath, title: base));
  }
}

await p.setQueue(tracks, startIndex: startIndex);
return _ok({'queued': tracks.length, 'startIndex': startIndex});

